	for _, child in ipairs(self.Preview.Model:GetChildren()) do
		if (child:IsA("Tool") or (child:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\8\187\228\84\41", "\49\69\212\128")) and (child.Name ~= "PreviewRig"))) then
			pcall(function()
				child:Destroy();
			end);
		end
