Hub.ReturnToSurface = function(self)
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local root = char and self:GetRoot(char);
	local hum = char and char:FindFirstChildOfClass("Humanoid");
	if not root then
		return;
	end
	local upParams = RaycastParams.new();
	upParams.FilterType = Enum.RaycastFilterType.Exclude;
	upParams.IgnoreWater = true;
	upParams.FilterDescendantsInstances = {char};
	local res = self.Services.Workspace:Raycast(root.Position, Vector3.new(0, 400, 0), upParams);
	local y = (res and (res.Position.Y + 4)) or (self.AutoFarm.DownRefY and (self.AutoFarm.DownRefY + 4)) or (root.Position.Y + 16);
	pcall(function()
		local _, ry, _ = root.CFrame:ToOrientation();
		root.CFrame = CFrame.new(root.Position.X, y, root.Position.Z) * CFrame.Angles(0, ry, 0);
		root.AssemblyLinearVelocity = Vector3.new(0, 0, 0);
		root.AssemblyAngularVelocity = Vector3.new(0, 0, 0);
	end);
	if hum then
		hum.PlatformStand = false;
		hum.Sit = false;
		hum:ChangeState(Enum.HumanoidStateType.GettingUp);
		task.defer(function()
			if (hum and not self.AutoFarm.IsActive) then
