			if data.Icon then
				self:Tween(data.Icon, {[LUAOBFUSACTOR_DECRYPT_STR_0("\228\214\58\2\206\7\194\215\52\23\152", "\68\173\187\91\101\171")]=self.Theme.TextDim}, 0.2);
			end
		end
	end
	if (tabName == LUAOBFUSACTOR_DECRYPT_STR_0("\202\6\1\210\72\142\110", "\185\156\111\114\167\41\226\29")) then
		if self.World.Section then
			self.World.Section.Visible = true;
